<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { api } from '../api'
import { state, activeJob, label, nameOf, perform, refresh, short, date } from '../state'
import JobList from '../components/JobList.vue'
const emit = defineEmits<{ openCandidate: [id: string]; library: []; jobs: [] }>()
const conditions = reactive({ condition_schema_version: '3.0.0', music_asset_id: '', model_bundle_id: 'baseline-v1', difficulty_class: 'IN', difficulty_value: 15, chart_mode: 'regular', key_count: null as number | null, performance_intensity: 45, performance_style: 'rhythm_linked', wildness: 25, generation_priority: 'playability', special_features: [] as string[], strict_playability: true, seed: 42, target_duration: 'full_song', target_engine: 'phira', noise_area: { generation_enabled: false } })
const normalized = ref<any>(null)
const ranges: Record<string, [number, number]> = { EZ: [0, 10], HD: [11, 14], IN: [14, 17], AT: [15, 18] }
const range = computed(() => ranges[conditions.difficulty_class]!)
const modes = [{ id: 'regular', title: '常规多线', text: '自由布局与受控的判定线演出', icon: '≋' }, { id: 'pure_keys', title: '固定键位', text: '真正的 4K / 5K / 6K 静态配置', icon: '▥' }, { id: 'anomaly', title: '特殊异像', text: '在已支持的能力范围内探索', icon: '✧' }]
const selectedMusic = computed(() => state.assets.find(a => a.id === conditions.music_asset_id))
const gpuBusy = computed(() => state.jobs.some(j => activeJob(j) && /train|generat|infer/.test(j.kind || j.type || '')))
const baselineId = computed(() => state.models.find(m => m.status === 'baseline_only')?.id || 'baseline-v1')
const availableModels = computed(() => state.models.filter(m => m.status !== 'baseline_only' && m.id !== 'baseline_only' && m.bundle_id !== 'baseline_only'))
const features = computed(() => {
  const src = state.capabilities.special_features || []
  return Array.isArray(src) ? src.map((x: any) => typeof x === 'string' ? { id: x, supported: false } : x) : Object.entries(src).map(([id, v]) => ({ id, ...(typeof v === 'object' ? v as any : { supported: v === true }) }))
})
function usable(m: any) { return m.available === true || m.usable === true || (m.checkpoint_sha256 && m.checkpoint_path && m.available !== false) }
function capability(mode: string) { return Array.isArray(state.capabilities.modes) ? state.capabilities.modes.find((m: any) => (m.id || m.mode) === mode) : null }
watch(() => conditions.difficulty_class, () => { conditions.difficulty_value = Math.min(range.value[1], Math.max(range.value[0], conditions.difficulty_value)) })
watch(() => conditions.chart_mode, mode => {
  conditions.key_count = mode === 'pure_keys' ? 4 : null
  conditions.special_features = []
  if (mode === 'pure_keys') { conditions.performance_intensity = 0; conditions.performance_style = 'none'; conditions.generation_priority = 'playability' }
  else { conditions.performance_intensity = 45; conditions.performance_style = 'rhythm_linked' }
})
watch(conditions, () => { normalized.value = null }, { deep: true })
watch(() => state.assets, () => { if (!conditions.music_asset_id && state.assets.length) conditions.music_asset_id = state.assets[0]!.id }, { immediate: true })
watch(baselineId, id => { if (conditions.model_bundle_id.startsWith('baseline')) conditions.model_bundle_id = id })
async function normalize() { await perform('normalize', async () => { normalized.value = await api('/generation-conditions/normalize', 'POST', { ...conditions }) }) }
async function generate() {
  if (!normalized.value) return
  await perform('generate', async () => { const res = await api('/generations', 'POST', normalized.value.effective_conditions || { ...conditions }); await refresh(); normalized.value = null; return res }, '生成任务已加入队列，可在右侧查看实际进度。')
}
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">CREATE SOMETHING PLAYABLE</p><h1>让音乐，成为可玩的谱面。</h1><p class="subtitle">从一首音乐开始。选择配置，生成初稿，再用听感与手感作出判断。</p></div><span class="badge outline">本地创作流程</span></div>
  <div class="workflow-strip"><div class="current"><span>01</span><strong>选择音乐与条件</strong></div><i>→</i><div><span>02</span><strong>生成与独立审计</strong></div><i>→</i><div><span>03</span><strong>人工预览与评分</strong></div><i>→</i><div><span>04</span><strong>导出与实机试玩</strong></div></div>
  <div class="generation-layout">
    <section class="panel generation-panel">
      <div class="panel-heading"><div><p class="section-kicker">新建谱面</p><h2>本次创作</h2></div><span class="step-pill">01 — 04</span></div>
      <div class="field"><label for="music">音乐素材 <span class="required">*</span></label><div class="input-action"><select id="music" v-model="conditions.music_asset_id"><option value="" disabled>选择已导入的音乐</option><option v-for="a in state.assets" :key="a.id" :value="a.id">{{ a.name }}</option></select><button class="button secondary" @click="emit('library')">＋ 导入音乐</button></div><p v-if="selectedMusic" class="field-hint">{{ label(selectedMusic.license_status) }} · {{ selectedMusic.allowed_actions?.map(label).join(' / ') || '尚未声明允许动作' }}</p><p v-else class="field-hint">音频仅上传到本机，不会发送给外部 API。</p></div>
      <div class="field"><label>谱面模式</label><div class="mode-grid"><button v-for="m in modes" :key="m.id" :disabled="capability(m.id)?.available === false" :title="capability(m.id)?.reason" :class="['mode-card', { selected: conditions.chart_mode === m.id }]" @click="conditions.chart_mode = m.id"><span class="mode-symbol">{{ m.icon }}</span><strong>{{ m.title }}</strong><small>{{ capability(m.id)?.available === false ? capability(m.id).reason : m.text }}</small><i class="radio-mark"></i></button></div></div>
      <div v-if="conditions.chart_mode === 'pure_keys'" class="soft-callout"><div class="row between"><div><strong>固定 {{ conditions.key_count }} 个键位，判定线全曲保持静止</strong><p>狂野度仅影响合法键位组合；演出与异像特性已关闭。</p></div><div class="segmented"><button v-for="k in [4,5,6]" :key="k" :class="{ active: conditions.key_count === k }" @click="conditions.key_count = k">{{ k }}K</button></div></div></div>
      <div class="form-grid"><div class="field"><label>难度类别</label><div class="segmented difficulty"><button v-for="c in ['EZ','HD','IN','AT']" :key="c" :class="[{ active: conditions.difficulty_class === c }, c.toLowerCase()]" @click="conditions.difficulty_class = c">{{ c }}</button></div></div><div class="field"><label for="difficulty">难度数值 <span class="muted">{{ range[0] }} – {{ range[1] }}</span></label><input id="difficulty" v-model.number="conditions.difficulty_value" type="number" :min="range[0]" :max="range[1]" step="1"></div></div>
      <div class="form-grid"><div class="field"><label for="intensity">演出强度 <strong>{{ conditions.performance_intensity }}<span class="muted"> / 100</span></strong></label><input id="intensity" v-model.number="conditions.performance_intensity" type="range" min="0" max="100" :disabled="conditions.chart_mode === 'pure_keys'"><p class="field-hint">{{ conditions.chart_mode === 'pure_keys' ? '固定键位模式关闭判定线演出。' : '控制判定线运动的活跃程度。' }}</p></div><div class="field"><label for="wildness">狂野度 <strong>{{ conditions.wildness }}<span class="muted"> / 100</span></strong></label><input id="wildness" v-model.number="conditions.wildness" type="range" min="0" max="100"><p class="field-hint">从克制的配置，到更丰富的节奏组合。</p></div></div>
      <div class="form-grid"><div class="field"><label for="style">演出风格</label><select id="style" v-model="conditions.performance_style" :disabled="conditions.chart_mode === 'pure_keys'"><option value="none">无演出</option><option value="calm">克制</option><option value="standard">标准</option><option value="rhythm_linked">跟随节奏</option><option value="ornate">丰富</option><option value="experimental">实验</option></select></div><div class="field"><label for="priority">生成优先级</label><select id="priority" v-model="conditions.generation_priority"><option value="playability">可玩性优先</option><option value="balanced">均衡</option><option v-if="conditions.chart_mode !== 'pure_keys'" value="performance">演出优先</option></select></div></div>
      <div v-if="conditions.chart_mode === 'anomaly'" class="field"><label>异像能力 <span class="muted">由本机能力矩阵决定</span></label><div v-if="features.length" class="feature-list"><label v-for="f in features" :key="f.id" class="checkbox"><input v-model="conditions.special_features" :value="f.id || f.feature_id" type="checkbox" :disabled="!(f.supported === true || f.state === 'supported' || f.capability_state === 'supported')"><span>{{ f.name || f.label || f.id }}<small>{{ f.reason || f.note || (!(f.supported === true || f.state === 'supported') ? '未验证支持，暂不可选' : '服务已声明支持') }}</small></span></label></div><div v-else class="soft-callout muted">服务尚未提供服务已声明支持的异像特性。可生成模式基础初稿，无法启用未验证特性。</div></div>
      <div class="divider"></div>
      <div class="field"><label for="model">生成来源</label><select id="model" v-model="conditions.model_bundle_id"><option :value="baselineId">规则基线 · 传统音频分析与规则初稿</option><option v-for="m in availableModels" :key="m.id || m.bundle_id" :value="m.id || m.bundle_id" :disabled="!usable(m)">{{ m.name || m.id || m.bundle_id }} · {{ usable(m) ? label(m.status) : '权重不可用' }}</option></select><p v-if="conditions.model_bundle_id === baselineId" class="field-hint">规则基线不代表训练模型已学会作谱。所有初稿仍需独立审计和人工审核。</p><p v-if="!availableModels.some(usable)" class="model-unavailable">◌ 当前没有可用的已训练权重，AI 模型生成暂不可用。</p></div>
      <div class="form-grid"><div class="field"><label for="seed">随机种子</label><div class="input-action"><input id="seed" v-model.number="conditions.seed" type="number" min="0" max="4294967295" step="1"><button class="button secondary" aria-label="生成随机种子" @click="conditions.seed = Math.floor(Math.random() * 4294967296)">↻</button></div></div><div class="field end-field"><label class="checkbox"><input v-model="conditions.strict_playability" type="checkbox"><span>启用严格可玩性约束</span></label><p class="field-hint">噪域只读保留，本版本不生成或修改噪域。</p></div></div>
      <div v-if="normalized" class="normalized-summary"><div class="row between"><strong>已核对生效条件</strong><span class="badge green">等待你开始</span></div><p>{{ label(normalized.effective_conditions?.chart_mode) }} · {{ normalized.effective_conditions?.key_count ? `${normalized.effective_conditions.key_count}K · ` : '' }}{{ normalized.effective_conditions?.difficulty_class }} {{ normalized.effective_conditions?.difficulty_value }} · seed {{ normalized.effective_conditions?.seed }}</p><p v-for="(o, i) in normalized.overrides || []" :key="i" class="field-hint">{{ o.field }}：{{ o.requested }} → {{ o.effective }}，{{ o.reason }}</p><details><summary>查看完整生效条件</summary><pre>{{ JSON.stringify(normalized.effective_conditions, null, 2) }}</pre></details></div>
      <div class="form-footer"><span class="muted micro">{{ gpuBusy ? '已有生成或训练任务，待当前任务结束后再开始。' : '生成后进入独立的非 AI 审计流程。' }}</span><button v-if="!normalized" class="button primary" :disabled="!state.connected || !conditions.music_asset_id || state.busy.normalize" @click="normalize">{{ state.busy.normalize ? '正在核对…' : '核对生成条件' }} <span>→</span></button><button v-else class="button primary" :disabled="state.busy.generate || gpuBusy || !state.connected" @click="generate">{{ state.busy.generate ? '正在提交…' : '开始生成' }} <span>✦</span></button></div>
    </section>
    <aside class="generation-aside"><section class="studio-note"><div class="art-grid" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><b>✦</b><span></span><span></span><span></span><span></span></div><p class="section-kicker">创作的最后一环，是你的判断</p><h3>先听见，<br>再看清，最后亲手玩。</h3><p>格式检查、自动演示与模型指标各有用途。最终的节奏、手感和表现，留给真人审核。</p></section><section class="panel"><div class="panel-heading compact"><h2>本机任务</h2><button class="text-button" @click="emit('jobs')">全部 →</button></div><JobList compact /></section><section class="panel guidance"><span class="eyebrow">工作台约定</span><p>01 <strong>原始素材保持只读</strong></p><p>02 <strong>每次修改创建新版本</strong></p><p>03 <strong>导出前核对审核证据</strong></p></section></aside>
  </div>
  <section class="panel recent-section"><div class="panel-heading"><div><p class="section-kicker">继续创作</p><h2>最近的候选谱面</h2></div><span class="muted micro">{{ state.candidates.length }} 个本地候选</span></div><div v-if="!state.candidates.length" class="empty"><span class="empty-icon">♫</span><strong>第一张谱面，从这里开始</strong><p>导入音乐并完成条件核对后，新候选会保存在这里。</p></div><div v-else class="candidate-grid"><button v-for="c in state.candidates.slice(0, 6)" :key="c.id" class="candidate-card" @click="emit('openCandidate', c.id)"><div class="row between"><span class="chart-art">{{ c.chart_mode === 'pure_keys' ? `${c.key_count}K` : '♫' }}</span><span class="badge">{{ label(c.status) }}</span></div><h3>{{ nameOf(c.music_asset_id) }}</h3><p>{{ label(c.chart_mode) }} · {{ c.conditions?.difficulty_class || '' }} {{ c.conditions?.difficulty_value ?? '' }}</p><div class="row between micro muted"><span>{{ short(c.id) }}</span><span>{{ date(c.created_at) }}</span></div><span class="card-link">打开审核工作台 →</span></button></div></section>
</template>
